import React, { useEffect, useState } from "react";
import Header from "./../../components/Header/Header";
import Footer from "./../../components/Footer/Footer";
import "./result-list-page.css";
import { useNavigate } from "react-router-dom";

const ResultListPage: React.FC = () => {
  interface Test {
    test_id: number;
    created_at: string;
  }

  interface TestData {
    incomplete_tests: Test[];
    tests_with_pending_results: Test[];
    tests_with_results: Test[];
  }

  const [testData, setTestData] = useState<TestData>({
    incomplete_tests: [],
    tests_with_pending_results: [],
    tests_with_results: [],
  });

  const [message, setMessage] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const navigate = useNavigate();

  useEffect(() => {
    let isMounted = true;

    const fetchTestData = async () => {
      try {
        const rollno = localStorage.getItem("rollno");
        console.log("Fetching data for Roll No:", rollno);

        if (!rollno) {
          if (isMounted) {
            setMessage("Roll number not found. Please log in.");
            setLoading(false);
          }
          return;
        }

        const response = await fetch("http://localhost:5000/resultlist", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ rollno }),
        });

        console.log("API Response Status:", response.status);

        if (isMounted) {
          if (response.ok) {
            const data = await response.json();
            console.log("Received Data:", data);

            setTestData({
              incomplete_tests: data.incomplete_tests || [],
              tests_with_pending_results: data.tests_with_pending_results || [],
              tests_with_results: data.tests_with_results || [],
            });
          } else {
            const errorData = await response.json();
            setMessage(`Error: ${errorData.error || "Failed to fetch test data."}`);
          }
          setLoading(false);
        }
      } catch (error: any) {
        if (isMounted) {
          console.error("Error fetching test data:", error);
          setMessage(`Error: ${error.message || "Something went wrong."}`);
          setLoading(false);
        }
      }
    };

    fetchTestData();

    return () => {
      isMounted = false;
    };
  }, []);

  const handleAction = async (testId: number, action: string) => {
    try {
      let endpoint = "";

      switch (action) {
        case "resume":
          endpoint = "http://localhost:5000/resume";
          break;
        case "check_result":
          endpoint = "http://localhost:5000/check_result";
          break;
        case "view_result":
          localStorage.setItem("test_id", testId.toString());
          navigate("/completion-page");
          return;
        default:
          return;
      }

      const response = await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ testId }),
      });

      if (response.ok) {
        const result = await response.json();
        console.log(`Action '${action}' Success:`, result);

        if (action === "check_result") {
          if (Array.isArray(result) && result.length > 0) {
            setTestData((prev) => ({
              ...prev,
              tests_with_pending_results: prev.tests_with_pending_results.filter(
                (test) => test.test_id !== testId
              ),
              tests_with_results: [
                ...prev.tests_with_results,
                { test_id: testId, created_at: new Date().toISOString() },
              ],
            }));
          } else {
            setMessage("No results available for this test yet.");
          }
        } else {
          setMessage(result.message || "Action completed successfully.");
        }
      } else {
        const errorData = await response.json();
        setMessage(`Error: ${errorData.error || "Failed to perform action."}`);
      }
    } catch (error: any) {
      setMessage(`Error: ${error.message || "Something went wrong."}`);
      console.error("Action Error:", error);
    }
  };

  return (
    <div className="App">
      <Header />
      <div className="main-content">
        <h2>Test Status</h2>

        {loading ? <p>Loading test data...</p> : null}
        {message && <p className="feedback-message">{message}</p>}

        <div className="test-list">
          <h3>Incomplete Tests</h3>
          {testData.incomplete_tests.length > 0 ? (
            testData.incomplete_tests.map((test) => (
              <div key={test.test_id} className="test-item">
                <span>Test ID: {test.test_id}</span>
                <span>Created at: {new Date(test.created_at).toLocaleString()}</span>
                <button onClick={() => handleAction(test.test_id, "resume")} className="action-button">
                  Resume
                </button>
              </div>
            ))
          ) : (
            <p>No incomplete tests.</p>
          )}

          <h3>Tests with Pending Results</h3>
          {testData.tests_with_pending_results.length > 0 ? (
            testData.tests_with_pending_results.map((test) => (
              <div key={test.test_id} className="test-item">
                <span>Test ID: {test.test_id}</span>
                <span>Created at: {new Date(test.created_at).toLocaleString()}</span>
                <button onClick={() => handleAction(test.test_id, "check_result")} className="action-button">
                  Check Result
                </button>
              </div>
            ))
          ) : (
            <p>No tests with pending results.</p>
          )}

          <h3>Tests with Results</h3>
          {testData.tests_with_results.length > 0 ? (
            testData.tests_with_results.map((test) => (
              <div key={test.test_id} className="test-item">
                <span>Test ID: {test.test_id}</span>
                <span>Created at: {new Date(test.created_at).toLocaleString()}</span>
                <button onClick={() => handleAction(test.test_id, "view_result")} className="action-button">
                  View Result
                </button>
              </div>
            ))
          ) : (
            <p>No tests with results.</p>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ResultListPage;
